<?php
namespace App\Controllers; use App\Controllers\BaseController; use CodeIgniter\HTTP\ResponseInterface;
class TaskWorkflow extends BaseController { private const STATUSES=['todo','in_progress','blocked','review','done']; public function updateStatus(int $id):ResponseInterface{$db=db_connect();$task=$db->table('tasks')->where('id',$id)->get()->getRowArray();if(!$task)return $this->json(['success'=>false,'message'=>'Task not found.'],404);$d=$this->input();$status=(string)($d['status']??'');if(!in_array($status,self::STATUSES,true))return $this->json(['success'=>false,'message'=>'Invalid workflow status.'],422);$reason=trim((string)($d['blocked_reason']??''));if($status==='blocked'&&$reason==='')return $this->json(['success'=>false,'message'=>'Please enter why this task is blocked.'],422);$actor=$this->actorId();$db->table('tasks')->where('id',$id)->update(['status'=>$status,'blocked_reason'=>$status==='blocked'?$reason:null,'status_changed_at'=>date('Y-m-d H:i:s'),'status_changed_by'=>$actor,'completed'=>$status==='done'?1:0]);try{if($db->tableExists('activity_logs')){$fields=$db->getFieldNames('activity_logs');$map=['project_id'=>$task['project_id']??null,'actor_id'=>$actor,'team_member_id'=>$actor,'action'=>'task.status_changed','event_type'=>'task.status_changed','subject_type'=>'task','subject_id'=>$id,'description'=>'Task status changed to '.$status,'created_at'=>date('Y-m-d H:i:s')];$row=[];foreach($map as $k=>$v)if(in_array($k,$fields,true))$row[$k]=$v;if(in_array('metadata',$fields,true))$row['metadata']=json_encode(['from'=>$task['status']??null,'to'=>$status,'blocked_reason'=>$reason]);if($row)$db->table('activity_logs')->insert($row);}}catch(\Throwable $e){log_message('warning','Workflow activity skipped: '.$e->getMessage());}return $this->json(['success'=>true,'task'=>$db->table('tasks')->where('id',$id)->get()->getRowArray()]);} private function actorId():?int{$id=(int)(session()->get('team_member_id')??0);return $id>0?$id:null;}private function input():array{return $this->request->getJSON(true)?:$this->request->getPost()?:[];}private function json(array $d,int $s=200):ResponseInterface{return $this->response->setStatusCode($s)->setJSON($d);} }
